namespace ApplyOptimizerContrasts;
internal static class ApplyDiagnostics
{
    internal const string FreshOutput = "Output directory must be new";
    internal const string Declarations = "Nine independent observational declarations required";
    internal const string Usage = "Usage: ApplyOptimizerContrasts installedOtpRoot repositoryRoot newOutput buildEvidence";
    internal const string Evidence = "Verified pinned source-build evidence is required";
    internal const string Input = "Genuine pending image changed";
    internal const string Runtime = "Invoked pinned JIT runtime evidence missing";
    internal const string Compile = "Native probe compilation or disassembly failed";
    internal const string Capture = "A native observation is incomplete; raw output retained";
    internal const string ProcessStart = "Apply optimizer oracle did not start";
}

using System.Security.Cryptography;
using System.Text.Json;
namespace ApplyOptimizerContrasts;
internal static class ApplyExporter
{
    internal static async Task Run(string[] arguments)
    {
        if (arguments.Length != ApplyNames.ArgumentCount)
            throw new ArgumentException(ApplyDiagnostics.Usage);
        string root = Path.GetFullPath(arguments[0]);
        string repository = Path.GetFullPath(arguments[1]);
        string output = Path.GetFullPath(arguments[2]);
        using var evidence = JsonDocument.Parse(await File.ReadAllBytesAsync(arguments[3]));
        JsonElement proof = evidence.RootElement;
        if (proof.GetProperty("SourceCommit").GetString() != ApplyNames.Commit || proof.GetProperty("SourceTag").GetString() != ApplyNames.Tag || !proof.GetProperty("SourceBuildCompleted").GetBoolean() || Path.GetFullPath(proof.GetProperty("InstalledOtpRoot").GetString()!) != root)
            throw new InvalidDataException(ApplyDiagnostics.Evidence);
        string log = proof.GetProperty("SourceBuildLog").GetString()!;
        byte[] buildLog = await File.ReadAllBytesAsync(log);
        if (Hash(buildLog) != proof.GetProperty("SourceBuildLogSha256").GetString() || (await File.ReadAllTextAsync(Path.Combine(root, "releases", ApplyNames.Release, "OTP_VERSION"))).Trim() != ApplyNames.Version)
            throw new InvalidDataException(ApplyDiagnostics.Evidence);
        byte[] input = await File.ReadAllBytesAsync(Path.Combine(repository, ApplyNames.Input));
        if (Hash(input) != ApplyNames.InputSha256)
            throw new InvalidDataException(ApplyDiagnostics.Input);
        if (Directory.Exists(output))
            throw new IOException(ApplyDiagnostics.FreshOutput);
        Directory.CreateDirectory(output);
        string capturedInput = Path.Combine(output, "input.beam");
        await File.WriteAllBytesAsync(capturedInput, input);
        await File.WriteAllBytesAsync(Path.Combine(output, "source-build.log"), buildLog);
        await File.WriteAllBytesAsync(Path.Combine(output, "source-build-evidence.json"), await File.ReadAllBytesAsync(arguments[3]));
        byte[] declarations = await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory, ApplyNames.Declarations));
        await File.WriteAllBytesAsync(Path.Combine(output, ApplyNames.Declarations), declarations);
        using var declared = JsonDocument.Parse(declarations);
        string[] scenarios = declared.RootElement.GetProperty("Names").EnumerateArray().Select(row => row.GetString()!).ToArray();
        if (scenarios.Length != ApplyNames.ScenarioCount)
            throw new InvalidDataException(ApplyDiagnostics.Declarations);
        string suffix = OperatingSystem.IsWindows() ? ".exe" : "";
        string erl = Path.Combine(root, "bin", "erl" + suffix);
        string erlc = Path.Combine(root, "bin", "erlc" + suffix);
        string version = "V={erlang:system_info(otp_release),erlang:system_info(version),erlang:system_info(emu_flavor),code:root_dir()},ok=file:write_file(" + Quote(Path.Combine(output,"runtime.etf")) + ",term_to_binary(V)),{\"29\",\"17.1\",jit," + Quote(root) + "}=V,halt(0).";
        ApplyProcessResult runtime = await Execute(erl, ["-noshell","-eval",version], Path.Combine(output,"runtime"));
        if (!Complete(runtime) || !File.Exists(Path.Combine(output,"runtime.etf")))
            throw new InvalidDataException(ApplyDiagnostics.Runtime);
        foreach (string name in new[] { ApplyNames.MainSource, ApplyNames.LocalSource })
            await File.WriteAllBytesAsync(Path.Combine(output,name),await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,name)));
        ApplyProcessResult compile = await Execute(erlc,["-Werror","+debug_info","-o",output,Path.Combine(output,ApplyNames.MainSource),Path.Combine(output,ApplyNames.LocalSource)],Path.Combine(output,"compile"));
        if (!Complete(compile))
            throw new InvalidDataException(ApplyDiagnostics.Compile);
        foreach (string module in new[] { ApplyNames.MainModule, ApplyNames.LocalModule })
        {
            string disassembly = "D=beam_disasm:file(" + Quote(Path.Combine(output,module+".beam")) + "),ok=file:write_file(" + Quote(Path.Combine(output,module+".disassembly.txt")) + ",iolist_to_binary(io_lib:format(\"~tp~n\",[D]))),halt(0).";
            if (!Complete(await Execute(erl,["-noshell","-eval",disassembly],Path.Combine(output,module+".disassemble"))))
                throw new InvalidDataException(ApplyDiagnostics.Compile);
        }
        var rows = new List<ApplyObservation>();
        foreach (string name in scenarios)
        {
            string directory = Path.Combine(output,name);
            Directory.CreateDirectory(directory);
            string evaluation = ApplyNames.MainModule + ":run(" + Quote(name) + "," + Quote(capturedInput) + "," + Quote(directory) + ").";
            ApplyProcessResult observed = await Execute(erl,["-noshell","-pa",output,"-eval",evaluation],Path.Combine(directory,"process"));
            string? stage = File.Exists(Path.Combine(directory,"stage.txt")) ? await File.ReadAllTextAsync(Path.Combine(directory,"stage.txt")) : null;
            bool captured = Complete(observed) && stage == "completed" && File.Exists(Path.Combine(directory,"actual.etf")) && File.Exists(Path.Combine(directory,"messages.etf"));
            rows.Add(new(name,observed,stage,captured,await Files(directory)));
            await Report(output,proof,declarations,rows,false);
        }
        await Report(output,proof,declarations,rows,true);
        if (rows.Any(row => !row.Captured))
            throw new InvalidDataException(ApplyDiagnostics.Capture);
    }

    private static bool Complete(ApplyProcessResult result) => result.ExitCode == 0 && !result.TimedOut && result.RawComplete;

    private static async Task<ApplyProcessResult> Execute(string executable,string[] arguments,string prefix)
    {
        await File.WriteAllTextAsync(prefix+".arguments.json",JsonSerializer.Serialize(arguments));

        return await ApplyProcess.Run(executable,arguments,prefix);
    }

    private static async Task<object[]> Files(string directory)
    {
        var files = new List<object>();
        foreach (string path in Directory.EnumerateFiles(directory).Order(StringComparer.Ordinal))
        {
            byte[] bytes = await File.ReadAllBytesAsync(path);
            files.Add(new { Name=Path.GetFileName(path),Length=bytes.Length,Sha256=Hash(bytes) });
        }

        return files.ToArray();
    }

    private static async Task Report(string output,JsonElement proof,byte[] declarations,List<ApplyObservation> rows,bool complete)
    {
        var report = new { Status="NativeObservationsOnlyHypothesesNotValidated",SourceCommit=ApplyNames.Commit,SourceTag=ApplyNames.Tag,BuildEvidence=proof,DeclarationSha256=Hash(declarations),Complete=complete,ExpectedExecutions=ApplyNames.ScenarioCount,ActualExecutions=rows.Count,Captured=rows.Count(row=>row.Captured),Results=rows,Files=await Files(output),SdkExpectedUsed=false,SemanticCompatibilityClaim=false };
        string target = Path.Combine(output,ApplyNames.Report);
        await File.WriteAllTextAsync(target+".tmp",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true})+"\n");
        File.Move(target+".tmp",target,true);
    }

    private static string Hash(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes));

    private static string Quote(string value) => "\"" + value.Replace("\\","\\\\").Replace("\"","\\\"") + "\"";
}

namespace ApplyOptimizerContrasts;
internal static class ApplyNames
{
    internal const string MainModule = "apply_optimizer_probe";
    internal const string LocalModule = "apply_optimizer_local";
    internal const string Commit = "ad05823719d77c8faee87348ea39513d4e2f99c5";
    internal const string Tag = "OTP-29.1.1";
    internal const string Version = "29.1.1";
    internal const string Release = "29";
    internal const string MainSource = "apply_optimizer_probe.erl";
    internal const string LocalSource = "apply_optimizer_local.erl";
    internal const string Declarations = "predeclared-contracts.json";
    internal const string Report = "apply-optimizer.json";
    internal const string Input = "tests/Erlang.Tests/Resources/BeamOnLoad/fresh-success/new/beam_on_load_fresh_success.beam";
    internal const string InputSha256 = "59C8A07B362337A38E76DB3661B6B91BF3650D235631FA7D47B20488365BC20D";
    internal const int ArgumentCount = 4;
    internal const int ScenarioCount = 9;
    internal const int TimeoutSeconds = 45;
    internal const int StreamDrainSeconds = 5;
    internal const int CaptureCancellationJoinSeconds = 5;
    internal const int KilledProcessWaitSeconds = 5;
}

using System.Diagnostics;
using System.Globalization;

namespace ApplyOptimizerContrasts;

internal static class ApplyProcess
{
    internal static async Task<ApplyProcessResult> Run(string executable, string[] arguments, string prefix)
    {
        var start = new ProcessStartInfo(executable)
        {
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };
        foreach (string argument in arguments)
            start.ArgumentList.Add(argument);
        using var process = Process.Start(start) ?? throw new IOException(ApplyDiagnostics.ProcessStart);
        using var captureStop = new CancellationTokenSource();
        await using var stdoutFile = File.Create(prefix + ".stdout");
        await using var stderrFile = File.Create(prefix + ".stderr");
        Task stdout = process.StandardOutput.BaseStream.CopyToAsync(stdoutFile, captureStop.Token);
        Task stderr = process.StandardError.BaseStream.CopyToAsync(stderrFile, captureStop.Token);
        bool timedOut = false;
        bool rawComplete = false;
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(ApplyNames.TimeoutSeconds));
        try
        {
            await process.WaitForExitAsync(deadline.Token);
        }
        catch (OperationCanceledException) when (deadline.IsCancellationRequested)
        {
            timedOut = true;
            try
            {
                process.Kill(entireProcessTree: true);
            }
            catch (InvalidOperationException) when (process.HasExited)
            {
            }
            await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(ApplyNames.KilledProcessWaitSeconds));
        }
        finally
        {
            if (process.HasExited)
                await File.WriteAllTextAsync(prefix + ".exit", process.ExitCode.ToString(CultureInfo.InvariantCulture) + "\n");
            if (!process.HasExited)
                captureStop.Cancel();
            try
            {
                await Task.WhenAll(stdout, stderr).WaitAsync(TimeSpan.FromSeconds(ApplyNames.StreamDrainSeconds));
                rawComplete = true;
            }
            catch (TimeoutException)
            {
                await File.WriteAllTextAsync(prefix + ".raw-complete", "false\n");
                captureStop.Cancel();
                process.StandardOutput.Close();
                process.StandardError.Close();
                try
                {
                    await Task.WhenAll(stdout, stderr).WaitAsync(TimeSpan.FromSeconds(ApplyNames.CaptureCancellationJoinSeconds));
                }
                catch (OperationCanceledException) when (captureStop.IsCancellationRequested)
                {
                }
                catch (ObjectDisposedException)
                {
                }
                catch (IOException) when (captureStop.IsCancellationRequested)
                {
                }
                catch (TimeoutException)
                {
                    _ = Task.WhenAll(stdout, stderr).ContinueWith(
                        completed => _ = completed.Exception,
                        CancellationToken.None,
                        TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously,
                        TaskScheduler.Default
                    );
                }
            }
            catch (OperationCanceledException) when (captureStop.IsCancellationRequested)
            {
            }
            await stdoutFile.FlushAsync();
            await stderrFile.FlushAsync();
            await File.WriteAllTextAsync(prefix + ".raw-complete", rawComplete ? "true\n" : "false\n");
        }

        return new(
            process.ExitCode,
            timedOut,
            rawComplete
        );
    }
}

namespace ApplyOptimizerContrasts;

internal sealed record ApplyProcessResult(
    int ExitCode,
    bool TimedOut,
    bool RawComplete
);

using ApplyOptimizerContrasts;
try
{
    await ApplyExporter.Run(args);

    return 0;
}
catch (Exception error)
{
    Console.Error.WriteLine(error);

    return 1;
}
